"""Сводит сохранённые опыты; не запускает и не изменяет модель."""
from pathlib import Path
from fractions import Fraction
from statistics import mean,stdev
import json,csv,shutil,subprocess
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(Path(p).read_text())
def write(p,v):Path(p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])+'\n'
def csvfile(path,rows):
    with Path(path).open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=rows[0],lineterminator='\n');w.writeheader();w.writerows(rows)
def money_delta(a,b):
    n=int((Fraction(b)-Fraction(a))*100)
    return ('-' if n<0 else '')+f'{abs(n)//100}.{abs(n)%100:02d}'
def fmt(x,d=2):
    if x is None:return '—'
    if isinstance(x,str):return x
    return f'{x:.{d}f}'
book={};allpairs={};summaries={}
for name in ['allocation','negotiation','rating','faults']:
    b=read(ROOT/f'.local/{name}-run.json') if (ROOT/f'.local/{name}-run.json').exists() else read(ROOT/'evidence/series-index.json')[name];p=ROOT/b['path'];book[name]=b;allpairs[name]=read(p/'pairs.json');summaries[name]=read(p/'summary.json')
    for filename in ['experiment.json','pairs.json','pairs.csv','summary.json','manifest.json']:
        shutil.copy2(p/filename,ROOT/'evidence'/name/filename)
    rows=[]
    for pair in allpairs[name]:
        for key,a in pair['a_metrics'].items():
            b=pair['b_metrics'][key];av,bv=a['value'],b['value'];delta=None if av is None or bv is None else (money_delta(av,bv) if a['unit']=='RUB' else bv-av)
            rows.append({'condition':pair['condition'],'seed':pair['seed'],'metric':key,'a':av,'b':bv,'delta':delta,'unit':a['unit'],'a_reason':a['reason'],'b_reason':b['reason'],'input_hash':pair['input_hash']})
    csvfile(ROOT/f'evidence/{name}/observations.csv',rows)
# Сопоставимая когорта: одна и та же заявка завершена в обоих вариантах.
cohort=[]
for pair in allpairs['negotiation']:
    p=ROOT/book['negotiation']['path']/'runs';a={o['id']:o for o in read(p/pair['a_result_id']/'orders.json')};b={o['id']:o for o in read(p/pair['b_result_id']/'orders.json')}
    common=[i for i in a if a[i]['outcome']==b[i]['outcome']=='completed']
